private val v44EN = VisualSpec(44, "Notification and sound", """<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 258" role="img" aria-label="Phone with reminder and separate calendar" font-family="Nunito Sans,sans-serif"><rect x="3" y="3" width="314" height="252" rx="12" fill="#F3FBF2"/><rect x="15" y="10" width="290" height="151" rx="15" fill="#064D2B"/><rect x="24" y="22" width="272" height="123" rx="8" fill="#E7F8DB"/><text x="36" y="43" font-size="12" font-weight="bold" fill="#064D2B">Notification area</text><text x="284" y="43" text-anchor="end" font-size="11" fill="#064D2B">14:30</text><g id="v44notice" visibility="visible"><rect x="32" y="53" width="256" height="76" rx="10" fill="white" stroke="#72B94C"/><rect x="43" y="65" width="31" height="31" rx="6" fill="#087C26"/><path d="M48 75 H69 M50 70 V77 M67 70 V77 M48 78 H69 V91 H48 Z" fill="none" stroke="white" stroke-width="1.5"/><text x="83" y="75" font-size="12" font-weight="bold" fill="#064D2B">Calendar · Reminder</text><text x="83" y="94" font-size="14" font-weight="bold" fill="#064D2B">Appointment at 3 PM</text><text x="83" y="113" font-size="11" fill="#064D2B">In 30 minutes</text></g><g id="v44empty" visibility="hidden"><text x="160" y="88" text-anchor="middle" font-size="13" fill="#064D2B">Reminder dismissed</text><text x="160" y="107" text-anchor="middle" font-size="12" fill="#064D2B">Notification area is empty</text></g><g id="v44bell" visibility="visible" stroke="#087C26" fill="none" stroke-width="2" stroke-linecap="round"><path d="M258 87 V77 Q265 64 272 77 V87 Z M262 91 H268 M253 73 Q247 81 253 89 M277 73 Q283 81 277 89"/></g><g id="v44mute" visibility="hidden" stroke="#064D2B" fill="none" stroke-width="2" stroke-linecap="round"><path d="M258 87 V77 Q265 64 272 77 V87 Z M262 91 H268 M254 67 L277 94"/></g><circle cx="160" cy="153" r="3" fill="#E7F8DB"/><path d="M160 163 V179" stroke="#72B94C" stroke-width="2" stroke-dasharray="3 3"/><rect x="15" y="181" width="290" height="66" rx="10" fill="#